.darma-loader-tw-avatar-stack { display: inline-flex; align-items: center; width: var(--loader-size, 130px); }
.darma-loader-tw-avatar-stack span { width: calc(var(--loader-size, 130px) * .34); height: calc(var(--loader-size, 130px) * .34); border-radius: 9999px; background: var(--loader-color, #8b5cf6); box-shadow: 0 0 0 calc(var(--loader-size, 130px) * .03) color-mix(in srgb, var(--loader-color, #8b5cf6) 18%, transparent); animation: darma-loader-tw-avatar-stack-twAvatar calc(var(--loader-speed, 1s) * 1.5) ease-in-out infinite; }
.darma-loader-tw-avatar-stack span:nth-child(2) { margin-left: calc(var(--loader-size, 130px) * -.12); background: var(--loader-secondary-color, #f59e0b); animation-delay: calc(var(--loader-speed, 1s) * .2); }
.darma-loader-tw-avatar-stack span:nth-child(3) { margin-left: calc(var(--loader-size, 130px) * -.12); animation-delay: calc(var(--loader-speed, 1s) * .4); }
@keyframes darma-loader-tw-avatar-stack-twAvatar { 0%, 100% { transform: translateY(0) scale(.88); opacity: .5; } 50% { transform: translateY(-14%) scale(1); opacity: 1; } }

